%% Protein Domain Prediction and CDM-based PPI Evaluation (Steps 7-10)
% Inputs:
%   ProteinClusteringResults.mat (generated by Steps 1-6)
%   PPIData.xlsx with columns ProteinA, ProteinB, Interaction
%
% Outputs:
%   PredictedProteinDomains.xlsx
%   PredictedPPI.xlsx
%   PPI_Evaluation_Metrics.xlsx
%
% Important:
% For a valid domain-prediction evaluation, use a held-out set of annotated
% proteins whose annotations were hidden during domain prediction. This
% script provides a basic cluster-majority baseline and flags the limitations.

clear; clc;

%% Load output from Steps 1-6
if ~isfile('ProteinClusteringResults.mat')
    error('ProteinClusteringResults.mat not found. Run Steps 1-6 first.');
end

S = load('ProteinClusteringResults.mat');
proteins = S.proteins;
clusterLabels = S.clusterLabels;
numClusters = S.numClusters;

if ~ismember('PfamDomains', proteins.Properties.VariableNames)
    error('Saved protein table does not contain PfamDomains.');
end

proteins.ProteinID = string(proteins.ProteinID);
proteins.PfamDomains = string(proteins.PfamDomains);
numProteins = height(proteins);

%% Parse existing Pfam annotations
domainLists = cell(numProteins, 1);

for i = 1:numProteins
    annotation = strtrim(proteins.PfamDomains(i));

    if ismissing(annotation) || strlength(annotation) == 0
        domainLists{i} = strings(0, 1);
    else
        parsed = strtrim(split(annotation, ';'));
        parsed = parsed(strlength(parsed) > 0);
        domainLists{i} = unique(parsed);
    end
end

%% STEP 7: Domain prediction using cluster-level domain frequencies
predictedDomains = strings(numProteins, 1);
predictionConfidence = nan(numProteins, 1);

for c = 1:numClusters
    clusterIdx = find(clusterLabels == c);
    hasKnown = cellfun(@(d) ~isempty(d), domainLists(clusterIdx));
    annotatedIdx = clusterIdx(hasKnown);

    if isempty(annotatedIdx)
        warning('Cluster %d has no annotated proteins; no prediction made.', c);
        continue;
    end

    allDomains = vertcat(domainLists{annotatedIdx});
    [uniqueDomains, ~, groupIdx] = unique(allDomains);
    domainCounts = accumarray(groupIdx, 1);
    [maxCount, bestIdx] = max(domainCounts);

    dominantDomain = uniqueDomains(bestIdx);
    confidence = maxCount / numel(annotatedIdx);

    for i = clusterIdx'
        if isempty(domainLists{i})
            predictedDomains(i) = dominantDomain;
            predictionConfidence(i) = confidence;
        end
    end
end

proteins.PredictedDomains = predictedDomains;
proteins.PredictionConfidence = predictionConfidence;
writetable(proteins, 'PredictedProteinDomains.xlsx');

%% STEP 8: Domain prediction evaluation
% Do NOT evaluate on the same proteins used to determine cluster-majority
% domains. For an unbiased estimate, create a held-out annotated test set,
% hide its Pfam annotations before Step 7, and evaluate those hidden labels.
%
% This section reports only a simple descriptive result for proteins with
% annotations and predictions; it is NOT a leakage-free test-set metric.
hasReference = cellfun(@(d) ~isempty(d), domainLists);
evalIdx = find(hasReference & strlength(predictedDomains) > 0);

if isempty(evalIdx)
    fprintf(['Step 8: No proteins have both reference annotations and ', ...
        'predictions. Use a held-out annotated test set for evaluation.\\n']);
else
    exactMatch = false(numel(evalIdx), 1);
    for j = 1:numel(evalIdx)
        i = evalIdx(j);
        % For the single-domain majority baseline, check whether the
        % predicted domain occurs anywhere in the reference domain set.
        exactMatch(j) = any(domainLists{i} == predictedDomains(i));
    end
    descriptiveAccuracy = mean(exactMatch);
    fprintf(['Step 8 descriptive domain hit rate (NOT held-out): %.2f%% ', ...
        'over %d proteins.\\n'], 100*descriptiveAccuracy, numel(evalIdx));
end

%% STEP 9: CDM PPI prediction using Jaccard similarity
ppiFile = 'PPIData.xlsx';
ppiData = readtable(ppiFile, 'VariableNamingRule', 'preserve');

requiredPPIColumns = {'ProteinA', 'ProteinB', 'Interaction'};
if ~all(ismember(requiredPPIColumns, ppiData.Properties.VariableNames))
    error('PPIData.xlsx must contain ProteinA, ProteinB, Interaction.');
end

ppiData.ProteinA = string(ppiData.ProteinA);
ppiData.ProteinB = string(ppiData.ProteinB);
ppiData.Interaction = double(ppiData.Interaction);

% Map protein identifiers to rows in the saved protein table.
[foundA, idxA] = ismember(ppiData.ProteinA, proteins.ProteinID);
[foundB, idxB] = ismember(ppiData.ProteinB, proteins.ProteinID);

numPairs = height(ppiData);
jaccardScores = nan(numPairs, 1);
predictedInteraction = nan(numPairs, 1);
jaccardThreshold = 0.3;  % Example threshold; use your validated threshold.

for i = 1:numPairs
    if ~foundA(i) || ~foundB(i)
        continue;
    end

    domainsA = domainLists{idxA(i)};
    domainsB = domainLists{idxB(i)};

    % If a protein has no reference annotation, use its predicted domain.
    if isempty(domainsA) && strlength(predictedDomains(idxA(i))) > 0
        domainsA = predictedDomains(idxA(i));
    end
    if isempty(domainsB) && strlength(predictedDomains(idxB(i))) > 0
        domainsB = predictedDomains(idxB(i));
    end

    % Leave the score NaN if either protein has no usable domain set.
    if isempty(domainsA) || isempty(domainsB)
        continue;
    end

    domainsA = unique(domainsA);
    domainsB = unique(domainsB);

    intersectionSize = numel(intersect(domainsA, domainsB));
    unionSize = numel(union(domainsA, domainsB));

    if unionSize == 0
        continue;
    end

    jaccardScores(i) = intersectionSize / unionSize;
    predictedInteraction(i) = ...
        double(jaccardScores(i) >= jaccardThreshold);
end

ppiData.JaccardSimilarity = jaccardScores;
ppiData.PredictedInteraction = predictedInteraction;
writetable(ppiData, 'PredictedPPI.xlsx');

fprintf('Step 9 complete. Wrote PredictedPPI.xlsx.\\n');

%% STEP 10: PPI evaluation
% Evaluate only pairs with known binary labels and valid computed scores.
validPPI = foundA & foundB & ...
    ismember(ppiData.Interaction, [0, 1]) & ...
    isfinite(jaccardScores) & isfinite(predictedInteraction);

actual = ppiData.Interaction(validPPI);
predicted = predictedInteraction(validPPI);

TP = sum(actual == 1 & predicted == 1);
TN = sum(actual == 0 & predicted == 0);
FP = sum(actual == 0 & predicted == 1);
FN = sum(actual == 1 & predicted == 0);

nEvaluated = TP + TN + FP + FN;
if nEvaluated == 0
    warning('No eligible PPI pairs for evaluation.');
    accuracy = NaN;
    precision = NaN;
    recall = NaN;
    specificity = NaN;
    f1Score = NaN;
    MCC = NaN;
else
    accuracy = (TP + TN) / nEvaluated;
    precision = TP / max(TP + FP, 1);
    recall = TP / max(TP + FN, 1);
    specificity = TN / max(TN + FP, 1);
    f1Score = 2 * precision * recall / max(precision + recall, eps);

    mccDenominator = sqrt( ...
        (TP + FP) * (TP + FN) * ...
        (TN + FP) * (TN + FN));

    if mccDenominator > 0
        MCC = (TP * TN - FP * FN) / mccDenominator;
    else
        MCC = NaN;
    end
end

fprintf('\\nPPI Evaluation Results\\n');
fprintf('Evaluated pairs: %d\\n', nEvaluated);
fprintf('TP: %d | TN: %d | FP: %d | FN: %d\\n', TP, TN, FP, FN);
fprintf('Accuracy: %.4f (%.2f%%)\\n', accuracy, 100*accuracy);
fprintf('Precision: %.4f\\n', precision);
fprintf('Recall: %.4f\\n', recall);
fprintf('Specificity: %.4f\\n', specificity);
fprintf('F1-score: %.4f\\n', f1Score);
fprintf('MCC: %.4f\\n', MCC);

Metrics = table(TP, TN, FP, FN, nEvaluated, accuracy, precision, ...
    recall, specificity, f1Score, MCC);
writetable(Metrics, 'PPI_Evaluation_Metrics.xlsx');

fprintf('Steps 7-10 complete.\\n');
